import{_ as o,o as a,c as r,ag as s}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Perguntas frequentes","description":"","frontmatter":{},"headers":[],"relativePath":"pt/faq.md","filePath":"pt/faq.md"}'),d={name:"pt/faq.md"};function t(i,e,n,c,l,u){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="perguntas-frequentes" tabindex="-1">Perguntas frequentes <a class="header-anchor" href="#perguntas-frequentes" aria-label="Permalink to &quot;Perguntas frequentes&quot;">​</a></h1><h2 id="a-consola-mostra-you-lack-the-required-entitlement" tabindex="-1">A consola mostra <code>You lack the required entitlement</code> <a class="header-anchor" href="#a-consola-mostra-you-lack-the-required-entitlement" aria-label="Permalink to &quot;A consola mostra `You lack the required entitlement`&quot;">​</a></h2><p>O script não está associado à conta Cfx.re que detém a license key do seu servidor. Verifique no <a href="https://portal.cfx.re" target="_blank" rel="noreferrer">Portal</a> se a conta que comprou o script é a mesma que criou a chave em <code>sv_licenseKey</code>. Os entitlements são lidos quando o servidor arranca: depois de uma nova compra, reinicie o servidor inteiro, um <code>restart</code> do recurso não chega.</p><h2 id="could-not-find-dependency-nay-lib-for-resource-nay-car-wash" tabindex="-1"><code>Could not find dependency nay_lib for resource nay_car_wash</code> <a class="header-anchor" href="#could-not-find-dependency-nay-lib-for-resource-nay-car-wash" aria-label="Permalink to &quot;`Could not find dependency nay_lib for resource nay_car_wash`&quot;">​</a></h2><p>O <code>nay_lib</code> tem de arrancar antes de todos os scripts Nayretis, e as duas pastas têm de estar na sua pasta <code>resources</code>. Verifique a ordem das linhas <code>ensure</code> no <code>server.cfg</code>: <code>ensure nay_lib</code> vem primeiro, logo a seguir aos recursos de framework, inventário e target.</p><h2 id="no-supported-framework-detected" tabindex="-1"><code>No supported framework detected</code> <a class="header-anchor" href="#no-supported-framework-detected" aria-label="Permalink to &quot;`No supported framework detected`&quot;">​</a></h2><p>Inicie o <code>nay_lib</code> depois do recurso do seu framework. Se a deteção continuar a falhar, force-a no <code>server.cfg</code>, por exemplo <code>setr nay:framework &quot;esx&quot;</code>. Os valores estão listados na página <a href="/pt/bridge/">Bridge</a>. Usa um framework que não é suportado? Escreva um <a href="/pt/bridge/custom">adaptador personalizado</a>.</p><h2 id="erros-de-base-de-dados-no-arranque" tabindex="-1">Erros de base de dados no arranque <a class="header-anchor" href="#erros-de-base-de-dados-no-arranque" aria-label="Permalink to &quot;Erros de base de dados no arranque&quot;">​</a></h2><p>O <code>oxmysql</code> tem de ser iniciado antes do <code>nay_lib</code> e estar ligado à sua base de dados (<code>mysql_connection_string</code> no <code>server.cfg</code>). As tabelas são criadas no primeiro arranque, por isso o utilizador da base de dados tem de ter permissão para criar tabelas.</p><h2 id="como-mudo-o-idioma" tabindex="-1">Como mudo o idioma? <a class="header-anchor" href="#como-mudo-o-idioma" aria-label="Permalink to &quot;Como mudo o idioma?&quot;">​</a></h2><p>Abra <code>/nay</code>, depois <strong>Nayretis</strong>, depois <strong>Idioma</strong>. Inglês, francês, espanhol, português, polaco e alemão estão incluídos, e o idioma aplica-se a todos os scripts Nayretis. <code>setr nay:locale &quot;fr&quot;</code> no <code>server.cfg</code> define o idioma usado até alguém o alterar no jogo.</p><h2 id="que-ficheiros-posso-editar" tabindex="-1">Que ficheiros posso editar? <a class="header-anchor" href="#que-ficheiros-posso-editar" aria-label="Permalink to &quot;Que ficheiros posso editar?&quot;">​</a></h2><ul><li><code>config.lua</code> de cada script: valores iniciais opcionais. Aplicam-se até uma definição ser alterada em <code>/nay</code>, e <strong>Repor</strong> volta a eles.</li><li><code>locales/*.json</code>: todos os textos mostrados aos jogadores.</li><li><code>nay_lib/bridge/custom.lua</code>: o seu próprio adaptador de framework.</li></ul><p>O resto do código está protegido pelo escrow da Cfx.</p><h2 id="o-nay-lib-liga-se-a-algum-sitio" tabindex="-1">O nay_lib liga-se a algum sítio? <a class="header-anchor" href="#o-nay-lib-liga-se-a-algum-sitio" aria-label="Permalink to &quot;O nay_lib liga-se a algum sítio?&quot;">​</a></h2><p>No arranque, o <code>nay_lib</code> lê um ficheiro público de versões (<code>https://versions.nayretis.com/versions.json</code>) e avisa na consola quando há uma atualização disponível. Desative isto com <code>set nay:versionCheck false</code>. Nada mais sai do seu servidor, a não ser que ative a <a href="/pt/nay-lib/api">API HTTP</a> ou adicione <a href="/pt/nay-lib/webhooks">webhooks</a>.</p><h2 id="onde-posso-obter-ajuda" tabindex="-1">Onde posso obter ajuda? <a class="header-anchor" href="#onde-posso-obter-ajuda" aria-label="Permalink to &quot;Onde posso obter ajuda?&quot;">​</a></h2><p>Abra uma publicação em <code>#support</code> no <a href="https://discord.gg/HqNyFsDBmw" target="_blank" rel="noreferrer">Discord da Nayretis</a>, uma publicação por problema, com o script e a respetiva versão, o seu framework, inventário e target, e os erros da consola do servidor e do F8.</p>',18)])])}const h=o(d,[["render",t]]);export{m as __pageData,h as default};
